"""Embeds text files (GLSL sources) as C++ byte arrays.

usage: embed_text.py <out.cpp> <out.h> <name>=<file> ...
Generates a table `hrl_vk_glsl_sources` of {name, text, size} entries.
"""
import sys

out_cpp, out_h = sys.argv[1], sys.argv[2]
entries = [a.split("=", 1) for a in sys.argv[3:]]

header = [
    "// Generated by tools/embed_text.py - do not edit.",
    "#ifndef HRL_VK_GLSL_SOURCES_GENERATED_H",
    "#define HRL_VK_GLSL_SOURCES_GENERATED_H",
    "#include <cstddef>",
    "struct HRL_VkGlslSource { const char* name; const char* text; size_t size; };",
    "extern const HRL_VkGlslSource hrl_vk_glsl_sources[];",
    f"constexpr size_t hrl_vk_glsl_source_count = {len(entries)};",
    "#endif",
]
source = ["// Generated by tools/embed_text.py - do not edit.", '#include "hrl_vk_glsl_sources.h"']
for i, (name, path) in enumerate(entries):
    with open(path, "rb") as f:
        data = f.read().replace(b"\r\n", b"\n")
    source.append(f"static const char text_{i}[] = {{")
    for k in range(0, len(data), 24):
        source.append(",".join(str(b) for b in data[k:k + 24]) + ",")
    source.append("0};")
table = ",\n".join(f'\t{{"{name}", text_{i}, {len(open(path, "rb").read().replace(b"""\r\n""", b"""\n"""))}}}' for i, (name, path) in enumerate(entries))
source.append("const HRL_VkGlslSource hrl_vk_glsl_sources[] = {")
source.append(table)
source.append("};")
with open(out_h, "w") as f:
    f.write("\n".join(header) + "\n")
with open(out_cpp, "w") as f:
    f.write("\n".join(source) + "\n")
